spec.setup_code:
var trueMarker = new api.THREE.Mesh(
                  new api.THREE.SphereGeometry(0.08, 16, 16),
                  new api.THREE.MeshPhongMaterial({ color: 0x2E86AB })
                );
                trueMarker.position.x = -0.4;
                api.group.add(trueMarker);
                var measuredMarker = new api.THREE.Mesh(
                  new api.THREE.SphereGeometry(0.08, 16, 16),
                  new api.THREE.MeshPhongMaterial({ color: 0xE8593C })
                );
                measuredMarker.position.x = 0.4;
                api.group.add(measuredMarker);
                var rod = new api.THREE.Mesh(
                  new api.THREE.CylinderGeometry(0.02, 0.02, 0.8, 8),
                  new api.THREE.MeshPhongMaterial({ color: 0xF2A65A })
                );
                rod.rotation.z = Math.PI / 2;
                api.group.add(rod);
                return {
                  update: function(t) {
                    api.group.rotation.y = t * 0.01;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cy = H / 2;
                    var trueX = W / 2 - 60;
                    var measuredX = W / 2 + 60;
                    ctx.strokeStyle = '#94A3B8';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(trueX, cy);
                    ctx.lineTo(measuredX, cy);
                    ctx.stroke();
                    ctx.fillStyle = '#2E86AB';
                    ctx.beginPath();
                    ctx.arc(trueX, cy, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(measuredX, cy, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#111827';
                    ctx.font = '14px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('true value', trueX, cy - 20);
                    ctx.fillText('measured value', measuredX, cy - 20);
                    ctx.fillText('absolute error = gap', (trueX + measuredX) / 2, cy + 30);
                  }
                };

return {
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var trueValue = controls.trueValue !== undefined ? controls.trueValue : 100;
                    var measured = controls.measured !== undefined ? controls.measured : 99.5;
                    var error = Math.abs(trueValue - measured);
                    ctx.fillStyle = '#111827';
                    ctx.font = '16px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText('True: ' + trueValue.toFixed(1) + '   Measured: ' + measured.toFixed(1), W / 2, H / 2 - 20);
                    ctx.font = 'bold 26px sans-serif';
                    ctx.fillStyle = '#E8593C';
                    ctx.fillText('Absolute error = ' + error.toFixed(2), W / 2, H / 2 + 20);
                  }
                };
